/* eslint-disable no-console, max-len -- dev tooling */
/**
 * Builds scripts/locale-table.js, the site's one locale table (page code and lh-edge import it),
 * from www's sitemap dataset (tools/source-export/feeds/sitemaps/roots.json: which roots exist,
 * their hreflang) and the hand-kept tools/markets/locale-data.json (status, names, home airport,
 * currency, time zone, shop language). A root of the hand-kept file that www does not have is an
 * error. test/locale-table.test.mjs checks that the generated file is up to date.
 * Usage: node tools/markets/build-locale-table.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
export const OUT = path.join(root, 'scripts/locale-table.js');

/** The table: { rows, defaultLocale, languageVersions, fallbackLanguageVersion }. */
export function buildTable(
  roots = JSON.parse(fs.readFileSync(path.join(root, 'tools/source-export/feeds/sitemaps/roots.json'), 'utf8')).roots,
  data = JSON.parse(fs.readFileSync(path.join(root, 'tools/markets/locale-data.json'), 'utf8')),
) {
  const www = new Map(roots.map((r) => [r.root, r]));
  const rows = {};
  Object.entries(data.roots).forEach(([key, row]) => {
    const r = www.get(key);
    if (!r || !r.ownSitemap) throw new Error(`${key}: not a root of www's sitemaps`);
    const [country, lang] = key.split('/');
    rows[key] = {
      country,
      lang,
      hreflang: r.hreflang.find((h) => h.includes('-')) || `${lang}-${country.toUpperCase()}`,
      status: row.status,
      documents: row.documents || 'own',
      name: row.name,
      countryName: row.countryName,
      homeAirport: row.homeAirport,
      currency: row.currency,
      timeZone: row.timeZone,
      shopLang: row.shopLang,
    };
  });
  [data.defaultLocale, data.fallbackLanguageVersion, ...Object.values(data.languageVersions)].forEach((k) => {
    if (!rows[k] || rows[k].status !== 'live') throw new Error(`${k}: must be a live row`);
  });
  Object.entries(rows).forEach(([k, r]) => {
    if (!['own', 'language'].includes(r.documents)) throw new Error(`${k}: documents must be own or language`);
    const version = data.languageVersions[r.lang];
    if (r.documents === 'language' && (!version || rows[version].documents !== 'own')) throw new Error(`${k}: documents language needs a language version of ${r.lang} with its own documents`);
  });
  return {
    rows,
    // every root of www (own sitemaps or only alternates): a path whose first two segments are
    // not one of them (/xf/lh/…) is not a root
    wwwRoots: roots.map((r) => r.root).sort(),
    defaultLocale: data.defaultLocale,
    languageVersions: data.languageVersions,
    fallbackLanguageVersion: data.fallbackLanguageVersion,
  };
}

/** A value as a JavaScript literal in the site's style (single quotes, unquoted keys, 2 spaces). */
export function literal(value, indent = '') {
  const pad = `${indent}  `;
  if (value === null || typeof value !== 'object') {
    return typeof value === 'string' ? `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'` : String(value);
  }
  const key = (k) => (/^[a-zA-Z_$][\w$]*$/.test(k) ? k : `'${k}'`);
  const entries = Object.entries(value);
  if (!entries.length) return '{}';
  return `{\n${entries.map(([k, v]) => `${pad}${key(k)}: ${literal(v, pad)},`).join('\n')}\n${indent}}`;
}

/** A value on one line ({ a: 'x', b: { c: null } }), the site's literal style otherwise. */
export function inline(value) {
  if (value === null || typeof value !== 'object') return literal(value);
  const key = (k) => (/^[a-zA-Z_$][\w$]*$/.test(k) ? k : `'${k}'`);
  const items = Array.isArray(value) ? value.map(inline) : Object.entries(value).map(([k, v]) => `${key(k)}: ${inline(v)}`);
  if (Array.isArray(value)) return `[${items.join(', ')}]`;
  return items.length ? `{ ${items.join(', ')} }` : '{}';
}

/** The rows, one per line (the table is loaded on every page: about 250 bytes a row). */
export function rowsLiteral(rows) {
  return `{\n${Object.entries(rows).map(([k, v]) => `  '${k}': ${inline(v)},`).join('\n')}\n}`;
}

/** The module text of scripts/locale-table.js. */
export function moduleText(table) {
  return `/* eslint-disable max-len, object-curly-newline -- generated, one row per line */
/* Generated by tools/markets/build-locale-table.mjs from www's sitemap dataset
   (tools/source-export/feeds/sitemaps/roots.json) and tools/markets/locale-data.json: do not
   edit here. status live: on Edge Delivery (the site treats it as migrated); pilot: rendered with
   its own row, links to it still go to www. documents own: every page is the root's own document;
   language: lh-edge answers the root from its language version's documents (LANGUAGE_VERSIONS)
   where it has none of its own. */

export const LOCALE_TABLE = ${rowsLiteral(table.rows)};

/** Every market-language root of www (its sitemap dataset), space-separated. */
export const WWW_ROOTS = ${literal(table.wwwRoots.join(' '))};

/** The locale of paths without a root (app screens, experience fragments, /index). */
export const DEFAULT_LOCALE = ${literal(table.defaultLocale)};

/** The documents (nav, footer, indexes) a root without a row uses: its language's version. */
export const LANGUAGE_VERSIONS = ${literal(table.languageVersions)};

/** A language without a version of its own (texts fall back to English). */
export const FALLBACK_LANGUAGE_VERSION = ${literal(table.fallbackLanguageVersion)};
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const table = buildTable();
  fs.writeFileSync(OUT, moduleText(table));
  console.log(`locale-table: ${Object.keys(table.rows).length} rows (${Object.values(table.rows).filter((r) => r.status === 'live').length} live)`);
}
